, "senses": [{"id": "e06e6007-6ca9-4e57-8416-f0c18438eba7", "pos": "noun", "gloss": "An animal that lives in water, breathes through gills, and has fins."}, {"id": "21733154-d4a9-4901-b247-fc535be53335", "pos": "verb", "gloss": "To try to catch fish."}, {"id": "02ccb300-b8dc-432c-876b-0188eb609afb", "pos": "verb", "gloss": "To try indirectly to obtain something from someone."}, {"id": "be34605f-655c-4083-80c9-8b55629c5b96", "pos": "noun", "gloss": "The flesh of fish eaten as food."}, {"id": "c11bb04b-f07a-4faf-a54d-b7403298fce5", "pos": "verb", "gloss": "To search for something by feeling around with the hands."}, {"id": "701dd6b6-f469-4874-afdf-6513e0a76029", "pos": "noun", "gloss": "A person of a particular kind or character."}, {"id": "0c660624-e278-4291-a54c-8507f389319d", "pos": "verb", "gloss": "To pull or take something out of a place, especially with difficulty."}], "inflectionOf": [], "variantOf": [], "cefr": [{"level": "A1", "pos": "noun", "source": "CEFR-J Wordlist"}, {"level": "B1", "pos": "verb", "source": "CEFR-J Wordlist"}], "caseVariants": []}, "target": null, "topic": null, "attempts": []}, "reviewed_at": "2026-11-12T06:20:57.475Z"}', '2026-11-12T04:41:14.741Z', '2026-11-12T04:41:14.741Z', '', NULL);
