INSERT OR IGNORE INTO work_passes ("entry_id", "type", "subject_id", "note", "holder", "created_at") VALUES ('9b4ed2f6-0aa9-4343-9b45-7f37741f78dd', 'parts', '86873f91-9809-47ec-a84c-f75652c56c07', 'This is itself a part of something; it has no main parts of its own.', 'agent:651a7aaf-8944-4117-89a5-4f4043c4eebd', '2026-11-10T23:50:22.066Z');
